import
    React from 'react';
import { NavLink, Outlet } from 'react-router-dom';
import "../../styles/roiTabs.css";
import "../../styles/RecordEntry.css";
export default function DashboardHome() {
    return (
        <div className="container">
            <h2>Automation Dashboard</h2>
            <div className="tabs">
                <NavLink className="roi-tab" to={`Dashboard_projects`}>Projects</NavLink>

                <NavLink className="roi-tab" to={`Dashboard_sprint`}>Sprints</NavLink>
                <NavLink className="roi-tab" to={`Dashboard_executions`}>Executions</NavLink>
                <NavLink className="roi-tab" to={`Dashboard_defects`}>Defects</NavLink>
                <NavLink className="roi-tab" to={`Dashboard_summary`}>Summary</NavLink>
            </div>
            <Outlet />
        </div>
    );
}
